import static org.junit.jupiter.api.Assertions.*;
import static io.restassured.RestAssured.given;
@QuarkusTest
@jakarta.enterprise.inject.Typed(FieldOperationsTest.class)
class FieldOperationsTest {
 record F(Long store,Long other,Long building,Long product,Long location,Long order,Long execution,Long item,String tote,String second,String picker,String manager,String manager2){}
 @jakarta.inject.Inject jakarta.persistence.EntityManager em;
 @jakarta.inject.Inject com.intermarche.backoffice.engine.executing.HandlingOrderService legacy;
 F f;
 String key(){return UUID.randomUUID().toString();}
 @BeforeEach void setup(){String code=key().substring(0,8);f=QuarkusTransaction.requiringNew().call(()->{
  var s=new Store();s.code="F-"+code;s.name="Terrain";s.persist();var other=new Store();other.code="O-"+code;other.name="Voisin";other.persist();
  for(String role:List.of("P","M","N")){var e=new Employee();e.badgeId=code+role;e.firstName="Test";e.lastName=role;e.email=e.badgeId+"@example.test";e.password=BCrypt.hashpw("test",BCrypt.gensalt(4));e.role=role.equals("P")?Employee.EmployeeRole.PICKER:Employee.EmployeeRole.MANAGER;e.store=s;e.active=true;e.persist();}
  var b=new StoreBuilding();b.buildingCode="F-B-"+code;b.persist();s.buildings.add(b);
  var p=new Product();p.ean="F"+code;p.name="Produit terrain";p.productType=ProductType.UNIT;p.temperatureZone=TemperatureZone.AMBIENT;p.referenceVolume=BigDecimal.ONE;p.persist();
  var l=new StoreShelfLocation();l.product=p;l.area="Z";l.aisle="A";l.unit="1";l.elevation="1";l.position="1";l.persist();b.locations.add(l);
  var fl=new FulfillmentLine();fl.product=p;fl.requestedQuantity=new BigDecimal("2");fl.location=l;fl.persist();var line=new LotLine();line.product=p;line.fulfillmentLine=fl;line.location=l;line.quantity=new BigDecimal("2");line.persist();
  var order=new ProductCollectingOrder();order.store=s;order.assignee=Employee.findByBadgeId(code+"P");order.code="FLD-"+code;order.status=BaseHandlingOrder.HandlingOrderStatus.PROCESSING;order.persist();var e=new PickingExecution();e.employee=order.assignee;e.handlingOrder=order;e.persist();var item=new PickedItem();item.product=p;item.lotLine=line;item.quantity=new BigDecimal("2");item.status=PickedItem.PickStatus.PENDING;item.persist();e.itemsToPick.add(item);
  for(String suffix:List.of("A","B")){var t=new Tote();t.code=code+suffix;t.store=s;t.toteType=Tote.ToteType.STANDARD;t.volume=new BigDecimal("60");t.persist();}
  return new F(s.id,other.id,b.id,p.id,l.id,order.id,e.id,item.id,code+"A",code+"B",code+"P",code+"M",code+"N");
 });f=new F(f.store,f.other,f.building,f.product,f.location,f.order,f.execution,f.item,f.tote,f.second,login(f.picker),login(f.manager),login(f.manager2));}
 String login(String username){return given().contentType("application/json").body(Map.of("username",username,"password","test")).post("/auth/login").then().statusCode(200).extract().path("token");}
 Response call(String token,String method,String path,Object body){var r=given().auth().oauth2(token).contentType("application/json");if(body!=null)r.body(body);var result=r.request(method,"/field-operations"+path);if(result.statusCode()>=400)System.out.println(path+" "+result.asString());return result;}
 Map<String,Object> report(String kind){var r=new LinkedHashMap<String,Object>();r.put("storeId",f.store);r.put("orderId",f.order);r.put("productId",f.product);r.put("locationId",f.location);r.put("requestKey",key());r.put("kind",kind);r.put("title","Produit à vérifier");r.put("comment","Emballage abîmé constaté sur place");r.put("observedAddress","Magasin · Z/A/1");return r;}
 Long incident(){return call(f.picker,"POST","/incidents",report("DAMAGED")).then().statusCode(200).extract().jsonPath().getLong("id");}
 String caseRevision(Long id){return call(f.manager,"GET","/incidents/"+id+"?storeId="+f.store,null).then().statusCode(200).extract().path("revision");}
 String orderRevision(){return given().auth().oauth2(f.picker).get("/handling-orders/operator/orders/"+f.order+"?storeId="+f.store).then().statusCode(200).extract().path("revision");}
 Response command(Map<String,Object> c){return given().auth().oauth2(f.picker).contentType("application/json").body(c).post("/handling-orders/operator/commands");}
 Map<String,Object> command(String action){return new LinkedHashMap<>(Map.of("storeId",f.store,"requestKey",key(),"executionId",f.execution,"action",action));}
 Map<String,Object> attach(String tote){var c=command("ADD_TOTE");c.put("toteCode",tote);c.put("usage","AMBIENT");command(c).then().statusCode(200);return c;}
 Map<String,Object> picked(){attach(f.tote);var c=command("PICK");c.putAll(Map.of("itemId",f.item,"quantity",2,"toteCode",f.tote));command(c).then().statusCode(200);return c;}
 Map<String,Object> correction(){picked();Long item=QuarkusTransaction.requiringNew().call(()->PickedItem.<PickedItem>find("loadedTote.tote.code",f.tote).firstResult().id);var c=command("RETURN_ITEM");c.putAll(Map.of("contractVersion",2,"expectedRevision",orderRevision(),"itemId",item,"toteCode",f.tote));return c;}
 Long approval(Long incident,Map<String,Object> command){return call(f.picker,"POST","/incidents/"+incident+"/approvals",Map.of("storeId",f.store,"requestKey",key(),"command",command)).then().statusCode(200).extract().jsonPath().getLong("id");}
 void approve(Long id){call(f.manager,"POST","/approvals/"+id+"/decision",Map.of("storeId",f.store,"requestKey",key(),"approve",true,"reason","Correction vérifiée" )).then().statusCode(200);}
 @Test void reportingIsContextualIdempotentAndDoesNotBlockOtherActions(){var r=report("MISSING");var first=call(f.picker,"POST","/incidents",r).then().statusCode(200).extract();long id=first.jsonPath().getLong("id");assertEquals(f.product.longValue(),first.jsonPath().getLong("product.id"));assertEquals(id,call(f.picker,"POST","/incidents",r).then().statusCode(200).extract().jsonPath().getLong("id"));r.put("comment","Contenu différent");call(f.picker,"POST","/incidents",r).then().statusCode(409);attach(f.tote);QuarkusTransaction.requiringNew().run(()->assertEquals(1,FieldIncident.count("store.id",f.store)));}
 @Test void managerTakesDecidesAndOperatorReceivesSameCaseHistory(){Long id=incident();var d=new LinkedHashMap<String,Object>(Map.of("storeId",f.store,"requestKey",key(),"expectedRevision",caseRevision(id),"action","CLAIM","reason","Je prends en charge"));call(f.picker,"POST","/incidents/"+id+"/decisions",d).then().statusCode(403);call(f.manager,"POST","/incidents/"+id+"/decisions",d).then().statusCode(200);call(f.manager,"POST","/incidents/"+id+"/decisions",d).then().statusCode(200);d.put("requestKey",key());d.put("action","RESOLVE");call(f.manager,"POST","/incidents/"+id+"/decisions",d).then().statusCode(409);d.put("expectedRevision",caseRevision(id));var closed=call(f.manager,"POST","/incidents/"+id+"/decisions",d).then().statusCode(200).extract();assertEquals("RESOLVED",closed.path("state"));assertEquals(3,closed.jsonPath().getList("history").size());var events=given().auth().oauth2(f.picker).get("/handling-orders/operator/support/events?storeId="+f.store+"&category=INSTRUCTION").then().statusCode(200).extract().jsonPath().getList("items");assertEquals(3,events.size());}
 @Test void casesAndAttachmentsStayWithinStoreAndActorScope(){Long id=incident();call(f.picker,"GET","/incidents/"+id+"?storeId="+f.other,null).then().statusCode(403);var bad=report("OTHER");bad.put("storeId",f.other);call(f.picker,"POST","/incidents",bad).then().statusCode(403);call(f.picker,"GET","/incidents?storeId="+f.store+"&limit=0",null).then().statusCode(400);call(f.picker,"GET","/incidents?storeId="+f.store+"&state=OPEN&productId="+f.product,null).then().statusCode(200).body("items.size()",org.hamcrest.Matchers.is(1));}
 @Test void photoControlsMimeSizeAndReplay(){Long id=incident();byte[] bytes;try{var image=new java.awt.image.BufferedImage(2,2,java.awt.image.BufferedImage.TYPE_INT_RGB);var out=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(image,"png",out);bytes=out.toByteArray();}catch(Exception e){throw new RuntimeException(e);}var r=new LinkedHashMap<String,Object>(Map.of("storeId",f.store,"requestKey",key(),"filename","constat.png","contentBase64",Base64.getEncoder().encodeToString(bytes)));long photo=call(f.picker,"POST","/incidents/"+id+"/attachments",r).then().statusCode(200).extract().jsonPath().getLong("id");assertEquals(photo,call(f.picker,"POST","/incidents/"+id+"/attachments",r).then().statusCode(200).extract().jsonPath().getLong("id"));given().auth().oauth2(f.picker).get("/handling-orders/operator/consultation/receipts/"+r.get("requestKey")+"?storeId="+f.store+"&kind=FIELD").then().statusCode(200);given().auth().oauth2(f.picker).get("/field-operations/incidents/"+id+"/attachments/"+photo+"?storeId="+f.store).then().statusCode(200).contentType("image/png");r.put("requestKey",key());r.put("contentBase64",Base64.getEncoder().encodeToString("<svg>bad</svg>".getBytes()));call(f.picker,"POST","/incidents/"+id+"/attachments",r).then().statusCode(400);}
 @Test void approvalDecisionMetadataProtectsRequesterAndExpiredRequests(){Long incident=incident();Long id=approval(incident,correction());var manager=call(f.manager,"GET","/incidents/"+incident+"/approvals?storeId="+f.store,null).then().statusCode(200).extract().jsonPath();assertEquals(true,manager.getBoolean("[0].canDecide"));var picker=call(f.picker,"GET","/incidents/"+incident+"/approvals?storeId="+f.store,null).then().statusCode(200).extract().jsonPath();assertEquals(false,picker.getBoolean("[0].canDecide"));QuarkusTransaction.requiringNew().run(()->SensitiveApproval.<SensitiveApproval>findById(id).expiresAt=DateTimeProvider.now().minusMinutes(1));var expired=call(f.manager,"GET","/incidents/"+incident+"/approvals?storeId="+f.store,null).then().statusCode(200).extract().jsonPath();assertEquals(false,expired.getBoolean("[0].canDecide"));assertEquals(true,expired.getBoolean("[0].expired"));}
 @Test void oneApprovedCorrectionAppliesOnlyOnceAndNeedsIndependentManager(){Long incident=incident();Long approval=approval(incident,correction());approve(approval);call(f.manager2,"POST","/approvals/"+approval+"/decision",Map.of("storeId",f.store,"requestKey",key(),"approve",true,"reason","Deuxième décision")).then().statusCode(409);String one=call(f.picker,"POST","/approvals/"+approval+"/apply?storeId="+f.store,null).then().statusCode(200).extract().asString();assertEquals(one,call(f.picker,"POST","/approvals/"+approval+"/apply?storeId="+f.store,null).then().statusCode(200).extract().asString());QuarkusTransaction.requiringNew().run(()->assertEquals(1,com.intermarche.backoffice.domain.executing.OperatorCommandReceipt.count("store.id=?1 and action='RETURN_ITEM'",f.store)));}
 @Test void changedBusinessRevisionAndExpiredApprovalAreRefused(){Long incident=incident();Long approval=approval(incident,correction());approve(approval);attach(f.second);call(f.picker,"POST","/approvals/"+approval+"/apply?storeId="+f.store,null).then().statusCode(409);QuarkusTransaction.requiringNew().run(()->SensitiveApproval.<SensitiveApproval>findById(approval).expiresAt=DateTimeProvider.now().minusMinutes(1));call(f.picker,"POST","/approvals/"+approval+"/apply?storeId="+f.store,null).then().statusCode(409);}
 @Test void acceptedDemandCreatesOneExistingReplenishmentDefinition(){var r=report("REPLENISHMENT");r.put("requestedQuantity","12");Long id=call(f.picker,"POST","/incidents",r).then().statusCode(200).extract().jsonPath().getLong("id");var definition=Map.of("storeId",f.store,"destinationBuildingId",f.building,"operation","TRUCK_UNLOADING","truckReference","TEST-CAMION","start",DateTimeProvider.now().plusMinutes(15).toString(),"end",DateTimeProvider.now().plusMinutes(45).toString(),"lines",List.of(Map.of("productId",f.product,"quantity","12")));var accept=Map.of("expectedRevision",caseRevision(id),"definition",definition);var one=call(f.manager,"POST","/incidents/"+id+"/replenishment",accept).then().statusCode(200).extract();long replenishment=one.jsonPath().getLong("replenishment.id");assertEquals("TO_ALLOCATE",one.path("replenishment.state"));assertEquals(replenishment,call(f.manager,"POST","/incidents/"+id+"/replenishment",accept).then().statusCode(200).extract().jsonPath().getLong("replenishment.id"));QuarkusTransaction.requiringNew().run(()->assertEquals(1,com.intermarche.backoffice.domain.replenishment.ReplenishmentDefinition.count("store.id",f.store)));}
 @Test void pauseKeepsPickedQuantitiesTotesAndAssignmentAndResumeUsesSameMission(){var pick=picked();var pause=Map.of("storeId",f.store,"requestKey",key(),"state","WAITING","reason","Attente d’un arbitrage","expectedRevision",orderRevision(),"expectedStateRevision","0");var state=call(f.picker,"PUT","/orders/"+f.order+"/state",pause).then().statusCode(200).extract();assertEquals("WAITING",state.path("state"));command(pick).then().statusCode(200);var add=command("ADD_TOTE");add.put("toteCode",f.second);add.put("usage","AMBIENT");command(add).then().statusCode(409);QuarkusTransaction.requiringNew().run(()->{assertEquals(0,new BigDecimal("2").compareTo(PickedItem.<PickedItem>find("loadedTote.tote.code",f.tote).firstResult().quantity));assertNotNull(BaseHandlingOrder.<BaseHandlingOrder>findById(f.order).assignee);});var resume=Map.of("storeId",f.store,"requestKey",key(),"state","ACTIVE","expectedRevision",orderRevision(),"expectedStateRevision",state.<String>path("stateRevision"));call(f.picker,"PUT","/orders/"+f.order+"/state",resume).then().statusCode(200);command(add).then().statusCode(200);}
 List<Response> parallel(java.util.concurrent.Callable<Response> a,java.util.concurrent.Callable<Response> b)throws Exception{var pool=java.util.concurrent.Executors.newFixedThreadPool(2);var gate=new java.util.concurrent.CountDownLatch(1);try{var one=pool.submit(()->{gate.await();return a.call();});var two=pool.submit(()->{gate.await();return b.call();});gate.countDown();return List.of(one.get(30,java.util.concurrent.TimeUnit.SECONDS),two.get(30,java.util.concurrent.TimeUnit.SECONDS));}finally{pool.shutdownNow();}}
 @Test void simultaneousReportsAndApprovalApplicationsDoNotDuplicateAnything()throws Exception{var r=report("DAMAGED");var reports=parallel(()->call(f.picker,"POST","/incidents",r),()->call(f.picker,"POST","/incidents",r));long id=reports.getFirst().then().statusCode(200).extract().jsonPath().getLong("id");assertEquals(id,reports.getLast().then().statusCode(200).extract().jsonPath().getLong("id"));Long approval=approval(id,correction());var decisions=parallel(()->call(f.manager,"POST","/approvals/"+approval+"/decision",Map.of("storeId",f.store,"requestKey",key(),"approve",true,"reason","Validation A")),()->call(f.manager2,"POST","/approvals/"+approval+"/decision",Map.of("storeId",f.store,"requestKey",key(),"approve",true,"reason","Validation B")));assertEquals(List.of(200,409),decisions.stream().map(Response::statusCode).sorted().toList());var applied=parallel(()->call(f.picker,"POST","/approvals/"+approval+"/apply?storeId="+f.store,null),()->call(f.picker,"POST","/approvals/"+approval+"/apply?storeId="+f.store,null));assertEquals(applied.getFirst().then().statusCode(200).extract().asString(),applied.getLast().then().statusCode(200).extract().asString());QuarkusTransaction.requiringNew().run(()->{assertEquals(1,FieldIncident.count("store.id",f.store));assertEquals(1,OperatorCommandReceipt.count("store.id=?1 and action='RETURN_ITEM'",f.store));});}
 @Test void concurrentMissionStateChangesArbitrateOnTheirObservedState()throws Exception{String revision=orderRevision();var a=Map.of("storeId",f.store,"requestKey",key(),"state","PAUSED","reason","Pause A","expectedRevision",revision,"expectedStateRevision","0");var b=Map.of("storeId",f.store,"requestKey",key(),"state","WAITING","reason","Attente B","expectedRevision",revision,"expectedStateRevision","0");var results=parallel(()->call(f.picker,"PUT","/orders/"+f.order+"/state",a),()->call(f.manager,"PUT","/orders/"+f.order+"/state",b));assertEquals(List.of(200,409),results.stream().map(Response::statusCode).sorted().toList());QuarkusTransaction.requiringNew().run(()->assertEquals(1,MissionStateChange.count("store.id",f.store)));}
 @Test void unrelatedPickerCannotReadTheCaseAndPhotoLimitsAreExplicit(){Long id=incident();String badge="P"+key().substring(0,8);QuarkusTransaction.requiringNew().run(()->{var e=new Employee();e.badgeId=badge;e.firstName="Autre";e.lastName="Préparateur";e.email=badge+"@example.test";e.password=BCrypt.hashpw("test",BCrypt.gensalt(4));e.role=Employee.EmployeeRole.PICKER;e.store=Store.findById(f.store);e.active=true;e.persist();});String other=login(badge);call(other,"GET","/incidents/"+id+"?storeId="+f.store,null).then().statusCode(404);call(other,"GET","/incidents?storeId="+f.store,null).then().statusCode(200).body("items.size()",org.hamcrest.Matchers.is(0));call(f.picker,"POST","/incidents/"+id+"/attachments",Map.of("storeId",f.store,"requestKey",key(),"filename","large.png","contentBase64","A".repeat(2_800_001))).then().statusCode(413);}

 @Test void caseListUsesAConstantSqlBudgetWithDifferentProducts()throws Exception{
  QuarkusTransaction.requiringNew().run(()->{var store=Store.<Store>findById(f.store);String badge=BaseHandlingOrder.<BaseHandlingOrder>findById(f.order).assignee.badgeId;for(int n=0;n<50;n++){var p=new Product();p.ean="FP"+f.store+"-"+n;p.name="Référence "+n;p.productType=ProductType.UNIT;p.temperatureZone=TemperatureZone.AMBIENT;p.persist();var i=new FieldIncident();i.store=store;i.product=p;i.reporter=badge;i.requestKey=key();i.fingerprint="performance";i.kind="OTHER";i.title="Dossier "+n;i.comment="Constat de test";i.persist();}});
  var statistics=em.getEntityManagerFactory().unwrap(org.hibernate.SessionFactory.class).getStatistics();statistics.setStatisticsEnabled(true);var rows=new ArrayList<Map<String,Object>>();
  for(int size:List.of(1,10,30)){long sql=statistics.getPrepareStatementCount(),loads=statistics.getEntityLoadCount(),start=System.nanoTime();call(f.manager,"GET","/incidents?storeId="+f.store+"&limit="+size,null).then().statusCode(200).body("items.size()",org.hamcrest.Matchers.is(size));rows.add(Map.of("rows",size,"sql",statistics.getPrepareStatementCount()-sql,"entityLoads",statistics.getEntityLoadCount()-loads,"httpMs",(System.nanoTime()-start)/1_000_000));}
  assertEquals(1,rows.stream().map(r->r.get("sql")).distinct().count(),"La lecture des dossiers ne doit pas introduire de N+1");assertEquals(1,rows.stream().map(r->r.get("entityLoads")).distinct().count(),"Les références produit ne doivent pas charger leurs graphes");new com.fasterxml.jackson.databind.ObjectMapper().writeValue(java.nio.file.Path.of("target/t16-case-list-performance.json").toFile(),Map.of("scaling",rows,"jpqlAttentionThresholdMs",100,"maxQueryMs",statistics.getQueryExecutionMaxTime()));
 }

 @Test void historicalExecutionServiceAlsoHonoursThePausedMission(){picked();var pause=Map.of("storeId",f.store,"requestKey",key(),"state","PAUSED","reason","Contrôle de la garde","expectedRevision",orderRevision(),"expectedStateRevision","0");call(f.picker,"PUT","/orders/"+f.order+"/state",pause).then().statusCode(200);assertThrows(IllegalArgumentException.class,()->legacy.addTote(f.execution,f.second,TemperatureZone.AMBIENT));QuarkusTransaction.requiringNew().run(()->assertEquals(0,LoadedTote.count("tote.code",f.second)));}

}
